const FULL_DIGEST_BITS = {BLAKE2b: 512, BLAKE2s: 256};

/**
 * Hex of the BLAKE3 test vector input of the given length.
 *
 * @param {number} length
 * @returns {string}
 */
function blake3VectorInputHex(length) {
    return Array.from({length}, (_, index) => (index % 251).toString(16).padStart(2, "0")).join("");
}

/**
 * The key argument for a reference case.
 *
 * @param {Object} testCase
 * @returns {Object|string}
 */
function keyArgument(testCase) {
    return testCase.keyFormat === "plain" ? testCase.key : {string: testCase.key, option: testCase.keyFormat};
}

/**
 * Recipe steps hashing hex input with the given operation, converting Raw output back to hex.
 *
 * @param {string} op
 * @param {Object[]} args
 * @param {string} encoding
 * @returns {Object[]}
 */
function hashRecipe(op, args, encoding) {
    const steps = [{op: "From Hex", args: ["None"]}, {op, args}];
    if (encoding === "Raw") steps.push({op: "To Hex", args: ["None", 0]});
    return steps;
}

TestRegister.addTests([
    ...BLAKE2_KNOWN_ANSWERS.map(vector => ({
        name: `${vector.op}: known answer, ${vector.input.length / 2} bytes input${vector.key ? ", keyed" : ""}`,
        input: vector.input,
        expectedOutput: vector.expected,
        recipeConfig: hashRecipe(vector.op, [String(FULL_DIGEST_BITS[vector.op]), "Hex", {string: vector.key, option: "Hex"}], "Hex"),
    })),
    ...BLAKE3_OFFICIAL_VECTORS.flatMap(vector => [
        {
            name: `BLAKE3: official vector, ${vector.length} bytes input`,
            input: blake3VectorInputHex(vector.length),
            expectedOutput: vector.hash,
            recipeConfig: hashRecipe("BLAKE3", [vector.hash.length / 2, "", "Hex"], "Hex"),
        },
        {
            name: `BLAKE3: official vector, ${vector.length} bytes input, keyed`,
            input: blake3VectorInputHex(vector.length),
            expectedOutput: vector.keyedHash,
            recipeConfig: hashRecipe("BLAKE3", [vector.keyedHash.length / 2, {string: BLAKE3_VECTOR_KEY, option: "UTF8"}, "Hex"], "Hex"),
        },
        {
            name: `BLAKE3: official vector, ${vector.length} bytes input, keyed, Hex key`,
            input: blake3VectorInputHex(vector.length),
            expectedOutput: vector.keyedHash,
            recipeConfig: hashRecipe("BLAKE3", [vector.keyedHash.length / 2, {string: BLAKE3_VECTOR_KEY_HEX, option: "Hex"}, "Hex"], "Hex"),
        },
    ]),
    ...REFERENCE_CASES.map((testCase, index) => ({
        name: `${testCase.op}: reference case ${index + 1}, ${testCase.input.length / 2} bytes input, size ${testCase.size}, ${testCase.encoding}${testCase.key ? `, ${testCase.keyFormat} key` : ""}`,
        input: testCase.input,
        expectedOutput: testCase.expected,
        recipeConfig: hashRecipe(
            testCase.op,
            testCase.op === "BLAKE3" ?
                [testCase.size, keyArgument(testCase), testCase.encoding] :
                [String(testCase.size), testCase.encoding, keyArgument(testCase)],
            testCase.encoding
        ),
    })),
]);
